package hotel.shanshui.validation;
import com.getcapacitor.*;import com.getcapacitor.annotation.*;import java.util.concurrent.*;
@CapacitorPlugin(name="StageTwo") public class StageTwoPlugin extends Plugin {private StageTwoStore s;private final ExecutorService w=Executors.newSingleThreadExecutor();@Override public void load(){s=new StageTwoStore(getContext());}private void run(PluginCall c,Callable<JSObject>x){w.execute(()->{try{c.resolve(x.call());}catch(Exception e){c.reject(e.getMessage(),e);}});}@PluginMethod public void read(PluginCall c){run(c,()->s.read());}@PluginMethod public void scenario(PluginCall c){run(c,()->s.scenario(c.getBoolean("fail",false)));}@PluginMethod public void undo(PluginCall c){run(c,()->s.undo());}@PluginMethod public void health(PluginCall c){run(c,()->s.health());}@PluginMethod public void reset(PluginCall c){run(c,()->{s.reset();return new JSObject().put("reset",true);});}}
